import csv
import glob
import os

import cv2
import numpy as np

frames = sorted(glob.glob('/root/keyframes_*.png'))
if not frames:
    raise SystemExit('No keyframes found')

templates = {
    'coins': '/root/coin.png',
    'enemies': '/root/enemy.png',
    'turtles': '/root/turtle.png',
}

# Load templates as grayscale
loaded_templates = {}
for name, path in templates.items():
    img = cv2.imread(path, cv2.IMREAD_GRAYSCALE)
    if img is None:
        raise SystemExit(f'Failed to load template: {path}')
    loaded_templates[name] = img


def count_objects(frame_img, template_img, threshold=0.9, dedup_min_dist=3):
    fh, fw = frame_img.shape[:2]
    th, tw = template_img.shape[:2]
    if th > fh or tw > fw:
        return 0
    res = cv2.matchTemplate(frame_img, template_img, cv2.TM_CCOEFF_NORMED)
    ys, xs = np.where(res >= threshold)
    if len(xs) == 0:
        return 0
    scores = res[ys, xs]
    candidates = sorted(zip(xs, ys, scores), key=lambda x: x[2], reverse=True)
    kept = []
    min_dist_sq = dedup_min_dist * dedup_min_dist
    for x, y, score in candidates:
        if all((x - kx) ** 2 + (y - ky) ** 2 >= min_dist_sq for kx, ky, _ in kept):
            kept.append((x, y, score))
    return len(kept)

rows = []
for frame_path in frames:
    frame = cv2.imread(frame_path, cv2.IMREAD_GRAYSCALE)
    if frame is None:
        raise SystemExit(f'Failed to load frame: {frame_path}')
    counts = {}
    for name, tmpl in loaded_templates.items():
        counts[name] = count_objects(frame, tmpl)
    rows.append({
        'frame_id': frame_path,
        'coins': counts['coins'],
        'enemies': counts['enemies'],
        'turtles': counts['turtles'],
    })

out_path = '/root/counting_results.csv'
with open(out_path, 'w', newline='') as f:
    writer = csv.DictWriter(f, fieldnames=['frame_id', 'coins', 'enemies', 'turtles'])
    writer.writeheader()
    writer.writerows(rows)

print(f'Wrote {len(rows)} rows to {out_path}')
